//! `buckle install agent`: writes agent.yaml, creates the state directory and
//! installs a service that keeps the agent running (systemd on Linux, launchd
//! on macOS, the Service Control Manager on Windows).
//!
//! Service definitions are generated by pure functions so their content is
//! tested without touching the host.

use crate::config::AgentConfig;
use crate::store::{Store, write_atomic};
use buckle_core::error::HumanizableResult;
use std::path::{Path, PathBuf};

/// The service name on every platform.
pub const SERVICE_NAME: &str = "buckle-agent";

/// The systemd unit path.
pub const SYSTEMD_UNIT_PATH: &str = "/etc/systemd/system/buckle-agent.service";

/// The launchd label and plist path.
pub const LAUNCHD_LABEL: &str = "com.sierrasoftworks.buckle-agent";

/// The launchd plist path.
pub const LAUNCHD_PLIST_PATH: &str =
    "/Library/LaunchDaemons/com.sierrasoftworks.buckle-agent.plist";

/// How `install` should behave.
#[derive(Debug, Clone, Default)]
pub struct InstallOptions {
    /// Write the files but do not install or start the service.
    pub no_service: bool,
    /// The binary the service runs; defaults to the current executable.
    pub exe: Option<PathBuf>,
}

/// Quotes an argument for a systemd `ExecStart=` line.
fn systemd_quote(arg: &str) -> String {
    if arg
        .chars()
        .any(|c| c.is_whitespace() || c == '"' || c == '\\' || c == '\'')
    {
        format!("\"{}\"", arg.replace('\\', "\\\\").replace('"', "\\\""))
    } else {
        arg.to_owned()
    }
}

fn xml_escape(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

/// The systemd unit running `exe agent --config <config>`.
pub fn systemd_unit(exe: &Path, config: &Path) -> String {
    format!(
        "[Unit]
Description=Buckle agent
Documentation=https://github.com/SierraSoftworks/buckle
Wants=network-online.target
After=network-online.target tailscaled.service

[Service]
Type=simple
ExecStart={} agent --config {}
Restart=always
RestartSec=5
KillMode=mixed
TimeoutStopSec=90

[Install]
WantedBy=multi-user.target
",
        systemd_quote(&exe.to_string_lossy()),
        systemd_quote(&config.to_string_lossy())
    )
}

/// The launchd daemon plist running `exe agent --config <config>`.
pub fn launchd_plist(exe: &Path, config: &Path) -> String {
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>{LAUNCHD_LABEL}</string>
  <key>ProgramArguments</key>
  <array>
    <string>{}</string>
    <string>agent</string>
    <string>--config</string>
    <string>{}</string>
  </array>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
  <key>ThrottleInterval</key>
  <integer>5</integer>
  <key>StandardOutPath</key>
  <string>/var/log/buckle-agent.log</string>
  <key>StandardErrorPath</key>
  <string>/var/log/buckle-agent.log</string>
</dict>
</plist>
"#,
        xml_escape(&exe.to_string_lossy()),
        xml_escape(&config.to_string_lossy())
    )
}

/// The `sc.exe` invocations that create, configure and start the Windows service.
pub fn windows_service_commands(exe: &Path, config: &Path) -> Vec<Vec<String>> {
    let bin_path = format!(
        "\"{}\" agent --config \"{}\"",
        exe.to_string_lossy(),
        config.to_string_lossy()
    );
    vec![
        vec![
            "create".into(),
            SERVICE_NAME.into(),
            "binPath=".into(),
            bin_path,
            "start=".into(),
            "auto".into(),
            "DisplayName=".into(),
            "Buckle agent".into(),
        ],
        vec![
            "failure".into(),
            SERVICE_NAME.into(),
            "reset=".into(),
            "0".into(),
            "actions=".into(),
            "restart/5000/restart/5000/restart/5000".into(),
        ],
        vec!["start".into(), SERVICE_NAME.into()],
    ]
}

/// Serialises the agent configuration as written to agent.yaml.
pub fn render_config(config: &AgentConfig) -> buckle_core::Result<String> {
    let yaml = serde_yaml::to_string(config).to_human_error()?;
    Ok(format!(
        "# Buckle agent configuration, written by `buckle install agent`.\n{yaml}"
    ))
}

/// Writes agent.yaml: mode 0600 when it carries a token, 0644 otherwise.
pub fn write_config(config: &AgentConfig, path: &Path) -> buckle_core::Result<()> {
    let mode = if config.bootstrap_token.is_some() {
        0o600
    } else {
        0o644
    };
    write_atomic(path, render_config(config)?.as_bytes(), mode)
}

async fn run(program: &str, args: &[String]) -> buckle_core::Result<()> {
    tracing::info!(command = %format!("{program} {}", args.join(" ")), "running");
    let status = tokio::process::Command::new(program)
        .args(args)
        .status()
        .await
        .map_err(|e| {
            buckle_core::error::wrap_user(
                e,
                format!("Could not run `{program}`."),
                &["Install the service manually, or re-run with --no-service."],
            )
        })?;
    if status.success() {
        Ok(())
    } else {
        Err(buckle_core::error::user(
            format!("`{program} {}` failed with {status}.", args.join(" ")),
            &["Run the command by hand to see why, or re-run with --no-service."],
        ))
    }
}

async fn install_service(exe: &Path, config_path: &Path) -> buckle_core::Result<()> {
    if cfg!(target_os = "linux") {
        write_atomic(
            Path::new(SYSTEMD_UNIT_PATH),
            systemd_unit(exe, config_path).as_bytes(),
            0o644,
        )?;
        run("systemctl", &["daemon-reload".into()]).await?;
        run(
            "systemctl",
            &["enable".into(), "--now".into(), SERVICE_NAME.into()],
        )
        .await?;
        // A reinstall picks up a new binary or configuration.
        run("systemctl", &["restart".into(), SERVICE_NAME.into()]).await
    } else if cfg!(target_os = "macos") {
        write_atomic(
            Path::new(LAUNCHD_PLIST_PATH),
            launchd_plist(exe, config_path).as_bytes(),
            0o644,
        )?;
        let _ = run(
            "launchctl",
            &["bootout".into(), format!("system/{LAUNCHD_LABEL}")],
        )
        .await;
        run(
            "launchctl",
            &[
                "bootstrap".into(),
                "system".into(),
                LAUNCHD_PLIST_PATH.into(),
            ],
        )
        .await
    } else if cfg!(windows) {
        for args in windows_service_commands(exe, config_path) {
            run("sc.exe", &args).await?;
        }
        Ok(())
    } else {
        Err(buckle_core::error::user(
            "Buckle does not know how to install a service on this platform.",
            &[
                "Re-run with --no-service and start `buckle agent --config <path>` with your init system.",
            ],
        ))
    }
}

/// Writes agent.yaml, creates the state directory and (unless `no_service`)
/// installs and starts the service.
pub async fn install(
    config: &AgentConfig,
    config_path: &Path,
    options: &InstallOptions,
) -> buckle_core::Result<()> {
    config.validate()?;
    write_config(config, config_path)?;
    tracing::info!(path = %config_path.display(), "wrote the agent configuration");
    Store::new(&config.state_dir).ensure()?;
    if options.no_service {
        return Ok(());
    }
    let exe = match &options.exe {
        Some(exe) => exe.clone(),
        None => std::env::current_exe().map_err(|e| {
            buckle_core::error::wrap_system(
                e,
                "Buckle could not determine the path of its own executable.",
                &["Re-run with --no-service and install the service by hand."],
            )
        })?,
    };
    install_service(&exe, config_path).await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_systemd_unit_restarts_the_agent_with_its_config() {
        let unit = systemd_unit(
            Path::new("/usr/local/bin/buckle"),
            Path::new("/etc/buckle/agent.yaml"),
        );
        assert!(
            unit.contains("ExecStart=/usr/local/bin/buckle agent --config /etc/buckle/agent.yaml")
        );
        assert!(unit.contains("Restart=always"));
        assert!(unit.contains("RestartSec=5"));
        assert!(unit.contains("After=network-online.target tailscaled.service"));
        assert!(unit.contains("WantedBy=multi-user.target"));
    }

    #[test]
    fn systemd_paths_with_spaces_are_quoted() {
        let unit = systemd_unit(
            Path::new("/opt/my tools/buckle"),
            Path::new("/etc/buckle/agent.yaml"),
        );
        assert!(unit.contains("ExecStart=\"/opt/my tools/buckle\" agent"));
    }

    #[test]
    fn the_launchd_plist_keeps_the_agent_alive() {
        let plist = launchd_plist(
            Path::new("/usr/local/bin/buckle"),
            Path::new("/etc/buckle/a&b.yaml"),
        );
        assert!(plist.contains("<string>/usr/local/bin/buckle</string>"));
        assert!(plist.contains("<string>/etc/buckle/a&amp;b.yaml</string>"));
        assert!(plist.contains("<key>KeepAlive</key>\n  <true/>"));
        assert!(plist.contains(LAUNCHD_LABEL));
    }

    #[test]
    fn the_windows_service_restarts_on_failure() {
        let cmds = windows_service_commands(
            Path::new(r"C:\Program Files\buckle\buckle.exe"),
            Path::new(r"C:\ProgramData\buckle\agent.yaml"),
        );
        assert_eq!(cmds[0][0], "create");
        assert!(cmds[0][3].starts_with("\"C:\\Program Files\\buckle\\buckle.exe\" agent --config"));
        assert!(cmds[1].iter().any(|a| a.starts_with("restart/5000")));
        assert_eq!(cmds[2], vec!["start", SERVICE_NAME]);
    }

    fn config(token: Option<&str>, state_dir: &Path) -> AgentConfig {
        let mut config: AgentConfig =
            serde_yaml::from_str("server: https://buckle.example:7700\n").expect("config");
        config.bootstrap_token = token.map(str::to_owned);
        config.state_dir = state_dir.to_path_buf();
        config.labels.insert("role".into(), "worker".into());
        config
    }

    #[cfg(unix)]
    fn mode(path: &Path) -> u32 {
        use std::os::unix::fs::PermissionsExt;
        std::fs::metadata(path).expect("stat").permissions().mode() & 0o777
    }

    #[tokio::test]
    async fn install_without_service_writes_a_loadable_private_config() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("etc/agent.yaml");
        let state = dir.path().join("state");
        let options = InstallOptions {
            no_service: true,
            exe: None,
        };
        install(&config(Some("bootstrap-secret"), &state), &path, &options)
            .await
            .expect("install");
        let loaded = AgentConfig::load(&path).expect("loads");
        assert_eq!(loaded.bootstrap_token.as_deref(), Some("bootstrap-secret"));
        assert_eq!(loaded.labels["role"], "worker");
        assert!(state.is_dir());
        #[cfg(unix)]
        assert_eq!(mode(&path), 0o600);

        install(&config(None, &state), &path, &options)
            .await
            .expect("reinstall");
        #[cfg(unix)]
        assert_eq!(mode(&path), 0o644);
    }
}
